# Parton luminosities are stored per ORDERED flavour pair, signed (see io.fluxes).
#   gg   : f_g(x1) f_g(x2)
#   q_fw : f_q(x1) f_qbar(x2)   (quark from beam 1, travelling along +z)
#   q_bw : f_qbar(x1) f_q(x2)
# The generator proton is p = g u c d s (no b).
QUARKS = {"u": 2, "d": 1, "s": 3, "c": 4}
FLUX_GROUPS = ("gg",) + tuple(f"{q}_{o}" for q in QUARKS for o in ("fw", "bw"))

# ------------------------------------------------------------------ models
# One-loop models (MadLoop libraries). theta = y_DM^2; stored rho_c = I_c / |M_SM,c|^2 at y_DM = 1.
# Mass windows: 100 GeV steps, +-300 GeV around every best fit (all truths, binned and unbinned)
# found with the full 900-3000 GeV scan on the 1-in-40 subsample:
#   Scalar minima 1261-1500 GeV -> 1000-1800;  VLF minima 1500-1742 GeV -> 1200-2000.
# A best fit on the edge of a window means the window must be extended (fit_hypothesis warns).
LOOP_MODELS = {
    "Scalar": dict(root=f"{PROC_DIR}/Scalar/MatrixElements", masses=list(range(1000, 1801, 100)),
                   channels={"gg": "P2_gg_ttx", "qq": "P0_uux_ttx"},
                   card=lambda M: {"MASS": {5000002: M, 5000012: M - 100.0}, "FRBLOCK": {1: 1.0}}),
    "VLF": dict(root=f"{PROC_DIR}/VLF/MatrixElements", masses=list(range(1200, 2001, 100)),
                channels={"gg": "P2_gg_ttx", "qq": "P0_uux_ttx"},
                card=lambda M: {"MASS": {5000006: M, 5000022: M - 100.0}, "FRBLOCK": {1: 1.0}}),
}

# Z' (DMsimp_s_spin1, LO standalone, JAMP-initialisation patched). theta = g_q g_t.
#   B = |M_Z'|^2                       = K / D
#   A = 2 Re(M_EW^* M_Z')  (gamma + Z)  = [(s - M^2) R + M Gamma I] / D,   D = (s - M^2)^2 + M^2 Gamma^2
# at g_q = g_t = 1. K, R, I depend only on the kinematics, so any (M, Gamma) is exact.
ZP_LIBS = {"A": f"{PROC_DIR}/z_prime/MatrixElements/Zprime_A", "B": f"{PROC_DIR}/z_prime/MatrixElements/Zprime_B"}
ZP_SUBDIRS = {"u": "P1_uux_ttx", "d": "P2_ddx_ttx"}
ZP_COUPLINGS = {"DMINPUTS": {4: 1.0, 5: 1.0, 9: 1.0, 6: 0.0, 7: 0.0, 8: 0.0, 25: 0.0, 27: 0.0}}
ZP_REF_POINTS = {"B": [(10000.0, 100.0)],                       # (M, Gamma) used to extract K
                 "A": [(10000.0, 0.0), (10000.0, 10000.0)]}     # used to extract R and I
ZP_WIDTHS = {"Zp01": 0.01, "Zp20": 0.20}                        # Gamma / M of the two benchmarks
ZP_MASSES = list(range(2000, 4501, 100))                        # fit grid (paper)

# ------------------------------------------------------------------ benchmarks (paper, Table 1)
